<?php require __DIR__.'/../inc/bootstrap.php'; require_admin(); $dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0755,true);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&!empty($_FILES['file'])&&$_FILES['file']['error']===UPLOAD_ERR_OK){$name=basename($_FILES['file']['name']);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$allowed=['zip','pdf','txt','jpg','jpeg','png','gif','webp','mp3','mp4'];if(in_array($ext,$allowed,true)){ $safe=preg_replace('/[^a-zA-Z0-9._-]/','_',$name);move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$safe);$msg='UPLOAD OK';}else $msg='FILE TYPE NOT ALLOWED';} ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FILES</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container"><div class="card"><h1>[ FILE SYSTEM ]</h1><p><?=e($msg)?></p><form method="post" enctype="multipart/form-data"><input type="file" name="file"><button>UPLOAD</button></form><h3>FILES</h3><?php foreach(array_diff(scandir($dir),['.','..']) as $f): ?><p><a href="../uploads/<?=urlencode($f)?>" target="_blank"><?=e($f)?></a></p><?php endforeach; ?><p><a href="index.php">BACK</a></p></div></main></body></html>
